            name: validated.name,
            email: validated.email,
            password: hashedPassword,
            role: targetRole,
            isActive: true,
            // Tenant-created Staff belong to that Tenant so they appear in /my-staff.
            managerId: creatorRole === 'Tenant' ? req.user.id : null,
        });

