            } catch (mailErr) {
                // Still answer generically â€” never leak whether the account exists.
                console.error("Password-reset email failed:", mailErr.message);
            }
        }

        return res.json(GENERIC_FORGOT_RESPONSE);
    } catch (err) {
        console.error("Forgot-password error:", err);
