import { describe, test, expect, beforeEach } from "vitest";
import {
  EVAL_STORAGE_KEY,
  EVAL_LABEL_MAP_KEY,
  SIM_USERS_KEY,
  DETECTION_OUTCOMES,
  assignLabel,
  removeMappedUser,
