$modal=@'
import { CONDITIONS, IDENTITY_LABELS, DETECTION_OUTCOMES } from '../constants/evaluation';

const EvaluationRecorderModal = ({ state, setState, onSave, origin }) => {
  if (!state?.open || !state.draft) return null;
  const { draft } = state;
  const isNoFace = draft.detectionOutcome === DETECTION_OUTCOMES.NO_FACE;

  return (
    <div className="evaluation-modal-backdrop" role="presentation">
      <section className="evaluation-recorder-modal" role="dialog" aria-modal="true" aria-label="Record live evaluation result">
        <header>
          <h3>Record Live Evaluation</h3>
          <p>{origin}</p>
        </header>
        <dl className="evaluation-modal-summary">
          <div><dt>Predicted label</dt><dd>{isNoFace ? 'No Face' : (draft.predictedLabel || 'Unknown')}</dd></div>
          <div><dt>Confidence</dt><dd>{draft.confidence == null ? 'N/A' : `${Math.round(draft.confidence * 100)}%`}</dd></div>
          <div><dt>Latency</dt><dd>{draft.latencyMs == null ? 'N/A' : `${draft.latencyMs} ms`}</dd></div>
          <div><dt>Origin</dt><dd>{origin}</dd></div>
        </dl>
        {state.message && <p className="evaluation-modal-message">{state.message}</p>}
        {draft.needsMapping && <a href="/facial-evaluation?tab=live">Assign evaluation label first</a>}
        {!isNoFace && (
          <label>Actual label
            <select value={state.actualLabel} onChange={(e) => setState((prev) => ({ ...prev, actualLabel: e.target.value }))}>
              {IDENTITY_LABELS.map((label) => <option key={label} value={label}>{label}</option>)}
            </select>
          </label>
        )}
        <label>Test condition
          <select value={state.condition} onChange={(e) => setState((prev) => ({ ...prev, condition: e.target.value }))}>
            {CONDITIONS.map((condition) => <option key={condition} value={condition}>{condition}</option>)}
          </select>
        </label>
        <label>Notes
          <textarea value={state.notes} onChange={(e) => setState((prev) => ({ ...prev, notes: e.target.value }))} rows={3} />
        </label>
        <div className="evaluation-modal-actions">
          <button type="button" className="eval-primary-btn" onClick={onSave} disabled={draft.needsMapping}>Save Evaluation</button>
          <button type="button" className="eval-secondary-btn" onClick={() => setState({ open: false, draft: null, actualLabel: 'P01', condition: 'Front', notes: '', message: '' })}>Cancel</button>
        </div>
      </section>
    </div>
  );
};

export default EvaluationRecorderModal;
